1	<!DOCTYPE html>
2	<html lang="en">
3	<head>
4	  <meta charset="UTF-8">
5	  <meta name="viewport" content="width=device-width, initial-scale=1.0">
6	  <meta name="description" content="An accessible, animated pulsing circle with adjustable speed and pause controls.">
7	  <meta name="color-scheme" content="dark">
8	  <meta name="theme-color" content="#0d0d17">
9	  <title>Pulsing Circle</title>
10	  <link rel="icon" href="data:,">
11	
12	  <style>
13	    :root {
14	      --circle-hue: #8ec5ff;
15	      --circle-core: #4a7dd9;
16	      --circle-shadow: #1f3a75;
17	      --cycle: 2.5s;
18	    }
19	    * {
20	      margin: 0;
21	      padding: 0;
22	      box-sizing: border-box;
23	    }
24	    body {
25	      width: 100vw;
26	      height: 100vh;
27	      height: 100dvh;
28	      display: flex;
29	      flex-direction: column;
30	      justify-content: center;
31	      align-items: center;
32	      gap: 24px;
33	      background: radial-gradient(circle at center, #1a1a2e 0%, #0d0d17 100%);
34	      overflow: hidden;
35	    }
36	    svg {
37	      width: min(400px, 80vmin);
38	      height: min(400px, 80vmin);
39	      overflow: visible;
40	      cursor: pointer;
41	      user-select: none;
42	      -webkit-tap-highlight-color: transparent;
43	      transition: filter 0.3s ease;
44	    }
45	    .circle-btn:hover svg {
46	      filter: brightness(1.08);
47	    }
48	    .ambient {
49	      fill: var(--circle-hue);
50	      opacity: 0.12;
51	      filter: blur(30px);
52	      animation: breathe var(--cycle) cubic-bezier(0.4, 0, 0.2, 1) infinite;
53	      transform-origin: 200px 200px;
54	      will-change: transform, opacity;
55	    }
56	    .core {
57	      animation: pulse var(--cycle) cubic-bezier(0.4, 0, 0.2, 1) infinite;
58	      transform-origin: 200px 200px;
59	      filter: url(#glow);
60	      will-change: transform, opacity;
61	    }
62	    .highlight {
63	      fill: url(#highlightGradient);
64	      transform-origin: 200px 200px;
65	      animation: pulse var(--cycle) cubic-bezier(0.4, 0, 0.2, 1) infinite;
66	      pointer-events: none;
67	      will-change: transform, opacity;
68	    }
69	    .ring {
70	      fill: none;
71	      stroke: var(--circle-hue);
72	      stroke-width: 2.5;
73	      transform-origin: 200px 200px;
74	      animation: ripple var(--cycle) cubic-bezier(0.2, 0.6, 0.4, 1) infinite;
75	      will-change: transform, opacity, stroke-width;
76	    }
77	    .ring--delay-1 {
78	      animation-delay: calc(var(--cycle) / 3);
79	    }
80	    .ring--delay-2 {
81	      animation-delay: calc(var(--cycle) / 3 * 2);
82	    }
83	    @keyframes pulse {
84	      0%, 100% {
85	        transform: scale(1);
86	        opacity: 0.9;
87	      }
88	      50% {
89	        transform: scale(1.05);
90	        opacity: 1;
91	      }
92	    }
93	    @keyframes breathe {
94	      0%, 100% {
95	        transform: scale(0.95);
96	        opacity: 0.1;
97	      }
98	      50% {
99	        transform: scale(1.1);
100	        opacity: 0.18;
101	      }
102	    }
103	    @keyframes ripple {
104	      0% {
105	        transform: scale(1);
106	        opacity: 0.6;
107	        stroke-width: 2.5;
108	      }
109	      100% {
110	        transform: scale(1.35);
111	        opacity: 0;
112	        stroke-width: 0.5;
113	      }
114	    }
115	    body.paused .core,
116	    body.paused .ring,
117	    body.paused .ambient,
118	    body.paused .highlight {
119	      animation-play-state: paused;
120	    }
121	    /* Force-paused until JS takes over (below), avoiding a flash of motion;
122	       once JS is ready, control defers entirely to body.paused so the user
123	       can still explicitly resume even with reduced motion preferred. */
124	    @media (prefers-reduced-motion: reduce) {
125	      body:not(.js-ready) .core,
126	      body:not(.js-ready) .ring,
127	      body:not(.js-ready) .ambient,
128	      body:not(.js-ready) .highlight {
129	        animation-play-state: paused;
130	      }
131	    }
132	    .speed-label {
133	      color: var(--circle-hue);
134	      font-family: system-ui, sans-serif;
135	      font-size: 0.85rem;
136	      letter-spacing: 0.05em;
137	      opacity: 0.85;
138	      user-select: none;
139	      text-align: center;
140	    }
141	    .hint {
142	      display: block;
143	      margin-top: 4px;
144	      font-size: 0.7rem;
145	      opacity: 1;
146	    }
147	    .controls {
148	      display: flex;
149	      align-items: center;
150	      gap: 12px;
151	      max-width: min(320px, 90vw);
152	    }
153	    .pause-btn {
154	      display: inline-flex;
155	      align-items: center;
156	      justify-content: center;
157	      width: 36px;
158	      height: 36px;
159	      padding: 0;
160	      border-radius: 50%;
161	      border: 1px solid var(--circle-hue);
162	      background: transparent;
163	      color: var(--circle-hue);
164	      cursor: pointer;
165	      touch-action: manipulation;
166	      transition: background 0.2s ease;
167	    }
168	    .pause-btn:hover {
169	      background: rgba(142, 197, 255, 0.15);
170	    }
171	    .pause-btn:focus-visible {
172	      outline: 2px solid var(--circle-hue);
173	      outline-offset: 2px;
174	    }
175	    @media (prefers-contrast: more) {
176	      .pause-btn {
177	        border-width: 2px;
178	      }
179	      .ring {
180	        stroke-width: 3.5;
181	      }
182	    }
183	    .pause-btn svg {
184	      width: 14px;
185	      height: 14px;
186	    }
187	    .circle-btn {
188	      display: inline-flex;
189	      padding: 0;
190	      border: none;
191	      background: none;
192	      cursor: pointer;
193	      touch-action: manipulation;
194	      -webkit-tap-highlight-color: transparent;
195	      border-radius: 50%;
196	    }
197	    .circle-btn:focus-visible {
198	      outline: none;
199	    }
200	    .circle-btn:focus-visible svg {
201	      outline: 2px solid var(--circle-hue);
202	      outline-offset: 8px;
203	      border-radius: 50%;
204	    }
205	  </style>
206	</head>
207	<body>
208	  <button type="button" class="circle-btn" id="circleBtn" aria-label="Pulsing blue circle animation. Click to change pulse speed." aria-describedby="speedText" title="Click to change pulse speed">
209	  <svg viewBox="0 0 400 400" focusable="false" aria-hidden="true">
210	    <defs>
211	      <radialGradient id="circleGradient" cx="35%" cy="35%" r="65%">
212	        <stop offset="0%" style="stop-color: var(--circle-hue)"/>
213	        <stop offset="55%" style="stop-color: var(--circle-core)"/>
214	        <stop offset="100%" style="stop-color: var(--circle-shadow)"/>
215	      </radialGradient>
216	      <radialGradient id="highlightGradient" cx="32%" cy="28%" r="22%">
217	        <stop offset="0%" stop-color="#ffffff" stop-opacity="0.55"/>
218	        <stop offset="100%" stop-color="#ffffff" stop-opacity="0"/>
219	      </radialGradient>
220	      <filter id="glow" x="-80%" y="-80%" width="260%" height="260%">
221	        <feGaussianBlur in="SourceGraphic" stdDeviation="10" result="blur"/>
222	        <feColorMatrix in="blur" type="matrix"
223	          values="0 0 0 0 0.55  0 0 0 0 0.77  0 0 0 0 1  0 0 0 0.9 0" result="tintedBlur"/>
224	        <feMerge>
225	          <feMergeNode in="tintedBlur"/>
226	          <feMergeNode in="SourceGraphic"/>
227	        </feMerge>
228	      </filter>
229	    </defs>
230	    <circle class="ambient" cx="200" cy="200" r="160"/>
231	    <circle class="ring" cx="200" cy="200" r="140"/>
232	    <circle class="ring ring--delay-1" cx="200" cy="200" r="140"/>
233	    <circle class="ring ring--delay-2" cx="200" cy="200" r="140"/>
234	    <circle class="core" cx="200" cy="200" r="140" fill="url(#circleGradient)"/>
235	    <circle class="highlight" cx="200" cy="200" r="140"/>
236	  </svg>
237	  </button>
238	  <div class="controls">
239	    <button type="button" class="pause-btn" id="pauseBtn" aria-pressed="false" aria-label="Pause animation" title="Pause animation">
240	      <svg id="pauseIcon" viewBox="0 0 24 24" fill="currentColor" aria-hidden="true">
241	        <path d="M6 4h4v16H6zM14 4h4v16h-4z"/>
242	      </svg>
243	    </button>
244	    <p class="speed-label" id="speedLabel">
245	      <span id="speedText" aria-live="polite">Normal speed</span>
246	      <span class="hint" aria-hidden="true">Click circle to change speed</span>
247	    </p>
248	  </div>
249	  <script>
250	    const circleBtn = document.getElementById('circleBtn');
251	    const speedText = document.getElementById('speedText');
252	    const pauseBtn = document.getElementById('pauseBtn');
253	    const pauseIcon = document.getElementById('pauseIcon');
254	    const animatedEls = document.querySelectorAll('.core, .ring, .ambient, .highlight');
255	    const PLAY_ICON = '<path d="M8 5l11 7-11 7z"/>';
256	    const PAUSE_ICON = '<path d="M6 4h4v16H6zM14 4h4v16h-4z"/>';
257	    const speeds = [
258	      { value: '2.5s', name: 'Normal speed' },
259	      { value: '1.2s', name: 'Fast speed' },
260	      { value: '4.5s', name: 'Slow speed' },
261	    ];
262	    const reducedMotionQuery = window.matchMedia('(prefers-reduced-motion: reduce)');
263	    let speedIndex = 0;
264	    let manuallyPaused = reducedMotionQuery.matches;
265	    // Once the user has explicitly toggled pause/play, respect that choice
266	    // instead of letting a later OS-level reduced-motion change override it.
267	    let userHasChosen = false;
268	
269	    const STORAGE_KEY = 'pulsing-circle-prefs';
270	    try {
271	      const saved = JSON.parse(localStorage.getItem(STORAGE_KEY));
272	      if (saved && Number.isInteger(saved.speedIndex) && speeds[saved.speedIndex]) {
273	        speedIndex = saved.speedIndex;
274	        circleBtn.style.setProperty('--cycle', speeds[speedIndex].value);
275	      }
276	      if (saved && typeof saved.manuallyPaused === 'boolean') {
277	        manuallyPaused = saved.manuallyPaused;
278	        userHasChosen = true;
279	      }
280	    } catch {
281	      // Ignore malformed or inaccessible storage; fall back to defaults.
282	    }
283	
284	    function savePrefs() {
285	      try {
286	        localStorage.setItem(STORAGE_KEY, JSON.stringify({ speedIndex, manuallyPaused }));
287	      } catch {
288	        // Storage may be unavailable (e.g. private browsing); ignore.
289	      }
290	    }
291	
292	    function updateLabels() {
293	      const { name } = speeds[speedIndex];
294	      speedText.textContent = manuallyPaused ? `${name} (paused)` : name;
295	    }
296	
297	    function cycleSpeed() {
298	      speedIndex = (speedIndex + 1) % speeds.length;
299	      const { value } = speeds[speedIndex];
300	      circleBtn.style.setProperty('--cycle', value);
301	      // Restart animations from the beginning so the new speed feels immediate
302	      // instead of jumping mid-cycle.
303	      animatedEls.forEach((el) => {
304	        el.style.animation = 'none';
305	        void el.offsetWidth;
306	        el.style.animation = '';
307	      });
308	      updateLabels();
309	      savePrefs();
310	    }
311	
312	    function applyPauseState() {
313	      document.body.classList.toggle('paused', document.hidden || manuallyPaused);
314	      pauseBtn.setAttribute('aria-pressed', String(manuallyPaused));
315	      pauseBtn.setAttribute('aria-label', manuallyPaused ? 'Resume animation' : 'Pause animation');
316	      pauseBtn.setAttribute('title', manuallyPaused ? 'Resume animation' : 'Pause animation');
317	      pauseIcon.innerHTML = manuallyPaused ? PLAY_ICON : PAUSE_ICON;
318	      updateLabels();
319	    }
320	
321	    function togglePause() {
322	      manuallyPaused = !manuallyPaused;
323	      userHasChosen = true;
324	      applyPauseState();
325	      savePrefs();
326	    }
327	
328	    circleBtn.addEventListener('click', cycleSpeed);
329	    pauseBtn.addEventListener('click', togglePause);
330	
331	    document.addEventListener('visibilitychange', applyPauseState);
332	
333	    reducedMotionQuery.addEventListener('change', (e) => {
334	      if (userHasChosen) return;
335	      manuallyPaused = e.matches;
336	      applyPauseState();
337	    });
338	
339	    // Keep multiple open tabs/windows of this page in sync with each other.
340	    window.addEventListener('storage', (e) => {
341	      if (e.key !== STORAGE_KEY || !e.newValue) return;
342	      try {
343	        const saved = JSON.parse(e.newValue);
344	        if (Number.isInteger(saved.speedIndex) && speeds[saved.speedIndex] && saved.speedIndex !== speedIndex) {
345	          speedIndex = saved.speedIndex;
346	          circleBtn.style.setProperty('--cycle', speeds[speedIndex].value);
347	        }
348	        if (typeof saved.manuallyPaused === 'boolean') {
349	          manuallyPaused = saved.manuallyPaused;
350	          userHasChosen = true;
351	        }
352	        applyPauseState();
353	      } catch {
354	        // Ignore malformed storage updates from other tabs.
355	      }
356	    });
357	
358	    applyPauseState();
359	    updateLabels();
360	    document.body.classList.add('js-ready');
361	  </script>
362	</body>
363	</html>
